<template>
  <div class="car-detail-container">
    <button @click="handleRequestOrder">Request Order</button>

    <div v-if="showForm" class="order-form">
      <form @submit.prevent="submitOrder">
        <input v-model="orderForm.name" placeholder="Full Name" required />
        <input v-model="orderForm.email" type="email" placeholder="Email" required />
        <input v-model="orderForm.phone" type="tel" placeholder="Phone Number" required />
        <button type="submit">Submit Order</button>
      </form>
    </div>
  </div>
</template>

<script>
import axios from 'axios';

export default {
  data() {
    return {
      isAuthenticated: false,
      showForm: false,
      orderForm: {
        name: '',
        email: '',
        phone: '',
      },
    };
  },
  async created() {
    await this.checkAuth();
  },
  methods: {
    async checkAuth() {
      try {
        const response = await axios.get('http://localhost:8000/api/authenticated/', {
          withCredentials: true
        });
        this.isAuthenticated = response.data.isAuthenticated;
      } catch (error) {
        console.error('Auth check failed:', error);
        this.isAuthenticated = false;
      }
    },
    async handleRequestOrder() {
      // Всегда проверяем актуальный статус перед действием
      await this.checkAuth();

      if (this.isAuthenticated) {
        this.showForm = true;
      } else {
        this.$router.push('/login'); // Используем Vue Router вместо window.location
      }
    },
    async submitOrder() {
      if (!this.orderForm.name || !this.orderForm.email || !this.orderForm.phone) {
        alert('Please fill out all fields.');
        return;
      }

      try {
        await axios.post(
          'http://localhost:8000/api/request-order/',
          this.orderForm,
          { withCredentials: true }
        );
        alert('Order submitted successfully!');
        this.showForm = false;
        this.orderForm = { name: '', email: '', phone: '' };
      } catch (error) {
        console.error('Order submission failed:', error);

        // Если ошибка 401 (Unauthorized), обновляем статус
        if (error.response?.status === 401) {
          this.isAuthenticated = false;
          this.showForm = false;
          this.$router.push('/login');
        } else {
          alert('Failed to submit the order. Please try again.');
        }
      }
    },
  },
};
</script>